package org.skhuconnect.admin.dashboard.service;
import org.junit.jupiter.api.Test; import org.skhuconnect.user.repository.UserRepository; import org.skhuconnect.petition.repository.PetitionRepository; import org.skhuconnect.comment.repository.CommentRepository; import org.skhuconnect.report.repository.ReportRepository; import org.skhuconnect.petition.entity.PetitionStatus; import org.skhuconnect.report.entity.ReportStatus; import static org.mockito.Mockito.*; import static org.assertj.core.api.Assertions.assertThat;
class AdminDashboardServiceTest { @Test void aggregatesConfirmedMetrics(){UserRepository u=mock(UserRepository.class); PetitionRepository p=mock(PetitionRepository.class); CommentRepository c=mock(CommentRepository.class); ReportRepository r=mock(ReportRepository.class); when(u.count()).thenReturn(10L); when(p.countByDeletedFalse()).thenReturn(8L); when(c.countByDeletedFalse()).thenReturn(20L); for(PetitionStatus s:PetitionStatus.values()) when(p.countByStatusAndDeletedFalse(s)).thenReturn(1L); for(ReportStatus s:ReportStatus.values()) when(r.countByStatus(s)).thenReturn(2L); var result=new AdminDashboardService(u,p,c,r).get(); assertThat(result.totalUsers()).isEqualTo(10); assertThat(result.totalPetitions()).isEqualTo(8); assertThat(result.totalComments()).isEqualTo(20); assertThat(result.petitionsByStatus()).hasSize(PetitionStatus.values().length); assertThat(result.reportsByStatus()).hasSize(ReportStatus.values().length); }}
